using UnityEngine;\n\nnamespace Bynker.Core\n{\n    [System.Serializable]\n    public enum ProfessionType\n    {\n        Engineer,      // Улучшает производство энергии и ремонт\n        Farmer,        // Улучшает производство еды и воды\n        Doctor,        // Улучшает здоровье, снижает потери населения\n        Scientist,     // Улучшает исследования и защиту от катастроф\n        Worker,        // Универсальный работник, базовая помощь всем системам\n        Soldier        // Помогает в обороне, снижает потери при прямых атаках\n    }\n\n    [System.Serializable]\n    public class Survivor\n    {\n        public string Name;\n        public ProfessionType Profession;\n        public float Morale = 50f;\n        public float Health = 100f;\n        public bool IsInjured = false;\n        public int DaysInBunker = 0;\n\n        public Survivor(string name, ProfessionType profession)\n        {\n            Name = name;\n            Profession = profession;\n        }\n    }\n\n    [CreateAssetMenu(fileName = \"ProfessionDefinition\", menuName = \"Bynker/Profession Definition\")]\n    public class ProfessionDefinition : ScriptableObject\n    {\n        [Header(\"Identity\")]\n        public ProfessionType Type;\n        public string ProfessionName;\n        public string Description;\n\n        [Header(\"Bonuses\")]\n        public float PowerProductionBonus = 0f;\n        public float FoodProductionBonus = 0f;\n        public float WaterProductionBonus = 0f;\n        public float HealthBonus = 0f;\n        public float CatastropheResistance = 0f;  // Снижает урон в %\n        public float DefenseBonus = 0f;\n\n        [Header(\"Penalties\")]\n        public float MoraleThreshold = 30f;  // Ниже этого значения профессионал работает хуже\n    }\n}\n"